 pub fn finish_turn(&self,slot:usize,generation:u64)->Result<(semio_framework_actor::RetainedTurnReceipt,u64,u64),ValueError>{let mut original=self.original.try_lock().map_err(|_|refusal("original Host root scope is exclusively borrowed"))?;let Some(DriverCheckout::Context{slot:owned,generation:version,turn})=original.checkout.as_ref()else{return Err(refusal("original Host root has no held context scope"))};if(*owned,*version)!=(slot,generation){return Err(refusal("original Host root finish belongs to another retained slot"))}let turn=*turn;{let mut credit=self.execution.try_lock().map_err(|_|refusal("original VM credit is exclusively borrowed"))?;if let Some(held)=credit.as_ref(){let receipt=if held.claimed{held.receipt.ok_or_else(||refusal("original VM crossing still owes its receipt"))?}else{semio_framework_actor::OriginalGuestExecutionReceipt{budget:held.budget,spent_fuel:Some(0),submitted:false}};if held.claimed{original.root.receive_narrowed_execution_receipt(slot,generation,receipt)?;}else{original.root.receive_execution_receipt(slot,generation,receipt)?;}*credit=None;}}let(receipt,work,execution)=original.root.finish_turn(slot,generation)?;original.treasury.return_turn(turn,receipt.spent)?;original.checkout=None;Ok((receipt,work,execution))}
